125	        // ─────────────────────────────────────────────────────────────────────
126	        // Main data fetch per server
127	        // ─────────────────────────────────────────────────────────────────────
128	        private static async Task GetOcrDataList(
129	            string connString,
130	            IXLWorksheet wsClient,
131	            IXLWorksheet wsJob,
132	            IXLWorksheet wsTotalJob,
133	            IXLWorksheet wsFormat,
134	            string serverName,
135	            RowPointers rows)
136	        {
137	            await Task.Run(() =>
138	            {
139	                DataSet adminData;
140	                try
141	                {
142	                    adminData = GetAdminData(connString, "OCR_ENABLED_COUNT", serverName);
143	                }
144	                catch (Exception ex)
145	                {
146	                    Logger.Error(ex, "Admin SP failed for server {0}", serverName);
147	                    return;
148	                }
149	
150	                if (adminData == null || adminData.Tables.Count < 2)
151	                {
152	                    Logger.Warn("Server {0}: No data from admin SP", serverName);
153	                    return;
154	                }
155	
156	                DataTable clientList = adminData.Tables[0];
157	                DataTable serverList = adminData.Tables[1];
158	
159	                Logger.Info("Server {0}: Clients={1}, DB rows={2}",
160	                    serverName, clientList.Rows.Count, serverList.Rows.Count);
161	
162	                // ── Sheet 1 ───────────────────────────────────────────────────
163	                AppendDataTable(wsClient, clientList, ref rows.ClientRow);
164	
165	                // ── Deduplicate by COMPANY_LICENSE ────────────────────────────
166	                var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
167	                var uniqueServers = serverList.AsEnumerable()
168	                    .Where(r => seen.Add(r["COMPANY_LICENSE"].ToString().Trim()))
169	                    .ToList();
170	
171	                Logger.Info("Server {0}: Unique companies = {1}",
172	                    serverName, uniqueServers.Count);
173	
174	                foreach (DataRow server in uniqueServers)
175	                {
176	                    string workingPeriod = server["WORKING_PERIOD"].ToString();
177	                    string companyLicense = server["COMPANY_LICENSE"].ToString();
178	                    string companyName = server["COMPANY_NAME"].ToString();
179	                    string clientConn = server["CON_STRING"].ToString();
180	
181	                    string enabledDate = ParseDateToYMD(server["ENABLED_ON"].ToString());
182	                    string disabledDate = string.IsNullOrWhiteSpace(
183	                                             server["DISABLED_ON"].ToString())
184	                                         ? ""
185	                                         : ParseDateToYMD(server["DISABLED_ON"].ToString());
186	
187	                    // ── Sheet 2: JOB_COUNT (daily breakdown) ──────────────────
188	                    Logger.Info("[{0}][{1}] calling JOB_COUNT", serverName, companyLicense);
189	                    DataTable jobData = GetClientData(
190	                        clientConn, "JOB_COUNT",
191	                        serverName, workingPeriod, companyLicense,
192	                        companyName, enabledDate, disabledDate);
193	                    Logger.Info("[{0}][{1}] JOB rows={2}",
194	                        serverName, companyLicense, jobData.Rows.Count);
195	                    AppendDataTable(wsJob, jobData, ref rows.JobRow);
196	
197	                    // ── Sheet 3: TOTAL_JOB_DETAILS (overall summary) ──────────
198	                    Logger.Info("[{0}][{1}] calling TOTAL_JOB_DETAILS", serverName, companyLicense);
199	                    DataTable totalJobData = GetClientData(
200	                        clientConn, "TOTAL_JOB_DETAILS",
201	                        serverName, workingPeriod, companyLicense,
202	                        companyName, enabledDate, disabledDate);
203	                    Logger.Info("[{0}][{1}] TOTAL_JOB rows={2}",
204	                        serverName, companyLicense, totalJobData.Rows.Count);
205	                    AppendDataTable(wsTotalJob, totalJobData, ref rows.TotalJobRow);
206	
207	                    // ── Sheet 4: FORMAT_COUNT (format details) ────────────────
208	                    Logger.Info("[{0}][{1}] calling FORMAT_COUNT", serverName, companyLicense);
209	                    DataTable formatData = GetClientData(
210	                        clientConn, "FORMAT_COUNT",
211	                        serverName, workingPeriod, companyLicense,
212	                        companyName, enabledDate, disabledDate);
213	                    Logger.Info("[{0}][{1}] FORMAT rows={2}",
214	                        serverName, companyLicense, formatData.Rows.Count);
215	                    AppendDataTable(wsFormat, formatData, ref rows.FormatRow);
216	                }
217	            });
218	        }
