220	        // ─────────────────────────────────────────────────────────────────────
221	        // Admin SP — OCR_AI_ENABLED_COUNT
222	        // ─────────────────────────────────────────────────────────────────────
223	        private static DataSet GetAdminData(
224	            string connString, string flag, string serverName)
225	        {
226	            using var con = new SqlConnection(connString);
227	            using var cmd = new SqlCommand("OCR_AI_ENABLED_COUNT", con)
228	            {
229	                CommandType = CommandType.StoredProcedure,
230	                CommandTimeout = 120
231	            };
232	
233	            cmd.Parameters.AddWithValue("@MFLAG", flag);
234	            cmd.Parameters.AddWithValue("@serverName", serverName);
235	
236	            var errParam = new SqlParameter("@ERRORMSG",
237	                System.Data.SqlDbType.NVarChar, -1)
238	            { Direction = ParameterDirection.Output };
239	            cmd.Parameters.Add(errParam);
240	
241	            var adapter = new SqlDataAdapter(cmd);
242	            var ds = new DataSet();
243	            adapter.Fill(ds);
244	
245	            string errMsg = errParam.Value?.ToString();
246	            if (!string.IsNullOrEmpty(errMsg))
247	                Logger.Warn("Admin SP Error [{0}]: {1}", serverName, errMsg);
248	
249	            return ds;
250	        }
251	
252	        // ─────────────────────────────────────────────────────────────────────
253	        // Client SP — OCR_AI_JOB_COUNT
254	        // ─────────────────────────────────────────────────────────────────────
255	        private static DataTable GetClientData(
256	            string connStr,
257	            string flag,
258	            string serverName,
259	            string workingPeriod,
260	            string companyLicense,
261	            string companyName,
262	            string enabledDate,
263	            string disabledDate)
264	        {
265	            try
266	            {
267	                using var conn = new SqlConnection(connStr);
268	                using var cmd = new SqlCommand("OCR_AI_JOB_COUNT", conn)
269	                {
270	                    CommandType = CommandType.StoredProcedure,
271	                    CommandTimeout = 180
272	                };
273	
274	                cmd.Parameters.AddWithValue("@MFLAG", flag);
275	                cmd.Parameters.AddWithValue("@Server_name", serverName);
276	                cmd.Parameters.AddWithValue("@WORKING_PERIOD", workingPeriod);
277	                cmd.Parameters.AddWithValue("@COMPANY_LICENSE", companyLicense);
278	                cmd.Parameters.AddWithValue("@COMPANY_NAME", companyName);
279	                cmd.Parameters.AddWithValue("@ENABLED_DATE", enabledDate);
280	                cmd.Parameters.AddWithValue("@DISABLED_DATE", disabledDate);
281	
282	                var errParam = new SqlParameter("@ERRORMSG",
283	                    System.Data.SqlDbType.NVarChar, -1)
284	                { Direction = ParameterDirection.Output };
285	                cmd.Parameters.Add(errParam);
286	
287	                var adapter = new SqlDataAdapter(cmd);
288	                var ds = new DataSet();
289	                adapter.Fill(ds);
290	
291	                string errMsg = errParam.Value?.ToString();
292	                if (!string.IsNullOrEmpty(errMsg))
293	                    Logger.Warn("Client SP Error [{0}][{1}][{2}]: {3}",
294	                        serverName, companyLicense, flag, errMsg);
295	
296	                // JOB_COUNT uses EXEC(@sql) with SET NOCOUNT ON
297	                // → result lands in Tables[0] (no PRINT statement)
298	                return ds.Tables.Count > 0 ? ds.Tables[0] : new DataTable();
299	            }
300	            catch (Exception ex)
301	            {
302	                Logger.Error(ex, "GetClientData failed [{0}][{1}][{2}]",
303	                    serverName, companyLicense, flag);
304	                return new DataTable();
305	            }
306	        }
307	
308	        // ─────────────────────────────────────────────────────────────────────
309	        // Append DataTable to worksheet
310	        // ─────────────────────────────────────────────────────────────────────
311	        private static void AppendDataTable(
312	            IXLWorksheet ws, DataTable table, ref int currentRow)
313	        {
314	            if (table == null || table.Rows.Count == 0) return;
315	
316	            if (currentRow == 1)
317	            {
318	                for (int col = 0; col < table.Columns.Count; col++)
319	                {
320	                    var cell = ws.Cell(currentRow, col + 1);
321	                    cell.Value = table.Columns[col].ColumnName;
322	                    cell.Style.Font.Bold = true;
323	                    cell.Style.Fill.BackgroundColor = XLColor.DarkBlue;
324	                    cell.Style.Font.FontColor = XLColor.White;
325	                    cell.Style.Alignment.Horizontal =
326	                        XLAlignmentHorizontalValues.Center;
327	                }
328	                currentRow++;
329	            }
330	
331	            foreach (DataRow row in table.Rows)
332	            {
333	                for (int col = 0; col < table.Columns.Count; col++)
334	                    ws.Cell(currentRow, col + 1).Value = row[col]?.ToString();
335	
336	                if (currentRow % 2 == 0)
337	                    ws.Range(currentRow, 1, currentRow, table.Columns.Count)
338	                      .Style.Fill.BackgroundColor = XLColor.LightGray;
339	
340	                currentRow++;
341	            }
342	        }
343	
344	        // ─────────────────────────────────────────────────────────────────────
345	        // Style sheet
346	        // ─────────────────────────────────────────────────────────────────────
347	        private static void StyleSheet(
348	            IXLWorksheet ws, string title, int lastDataRow, int colCount)
349	        {
350	            try
351	            {
352	                ws.Row(1).InsertRowsAbove(1);
353	                int usedCols = colCount > 0
354	                    ? colCount
355	                    : ws.LastColumnUsed()?.ColumnNumber() ?? 1;
356	
357	                var titleRange = ws.Range(1, 1, 1, usedCols);
358	                titleRange.Merge();
359	                titleRange.FirstCell().Value = title;
360	                titleRange.Style.Font.Bold = true;
361	                titleRange.Style.Font.FontSize = 14;
362	                titleRange.Style.Alignment.Horizontal =
363	                    XLAlignmentHorizontalValues.Center;
364	                titleRange.Style.Fill.BackgroundColor = XLColor.Navy;
365	                titleRange.Style.Font.FontColor = XLColor.White;
366	
367	                ws.SheetView.FreezeRows(2);
368	
369	                if (ws.RangeUsed() != null)
370	                {
371	                    ws.RangeUsed().Style.Border.OutsideBorder =
372	                        XLBorderStyleValues.Thin;
373	                    ws.RangeUsed().Style.Border.InsideBorder =
374	                        XLBorderStyleValues.Thin;
375	                }
376	
377	                ws.Columns().AdjustToContents();
378	            }
379	            catch (Exception ex)
380	            {
381	                Logger.Warn("StyleSheet failed for {0}: {1}", ws.Name, ex.Message);
382	            }
383	        }
384	
385	        // ─────────────────────────────────────────────────────────────────────
386	        // Parse dd-MM-yyyy → yyyy-MM-dd
387	        // ─────────────────────────────────────────────────────────────────────
388	        private static string ParseDateToYMD(string dateStr)
389	        {
390	            if (string.IsNullOrWhiteSpace(dateStr)) return "";
391	            try
392	            {
393	                return DateTime.ParseExact(dateStr.Trim(), "dd-MM-yyyy", null)
394	                               .ToString("yyyy-MM-dd");
395	            }
396	            catch
397	            {
398	                Logger.Warn("Could not parse date: {0}", dateStr);
399	                return dateStr;
400	            }
401	        }
402	
403	        // ─────────────────────────────────────────────────────────────────────
404	        // Send email with Excel attachment
405	        // ─────────────────────────────────────────────────────────────────────
406	        private static async Task SendEmailWithAttachment(string filePath)
407	        {
408	            try
409	            {
410	                Logger.Info("Sending email...");
411	
412	                string reportDate = DateTime.Now.AddDays(-1).ToString("dd-MM-yyyy");
413	                string subject = _smtpSettings.Subject.Replace("{Date}", reportDate);
414	                string htmlBody = _smtpSettings.Body.Replace("{Date}", reportDate);
415	
416	                using var mail = new MailMessage
417	                {
418	                    From = new MailAddress(
419	                                     _smtpSettings.FromEmail,
420	                                     _smtpSettings.Mail_header),
421	                    Subject = subject,
422	                    IsBodyHtml = true
423	                };
424	
425	                string logoPath = Path.Combine(
426	                    AppContext.BaseDirectory, "Assets", "Company_Logo.png");
427	
428	                if (File.Exists(logoPath))
429	                {
430	                    var htmlView = AlternateView.CreateAlternateViewFromString(
431	                        htmlBody, null, "text/html");
432	                    var logoRes = new LinkedResource(logoPath, "image/png")
433	                    { ContentId = "companylogo" };
434	                    htmlView.LinkedResources.Add(logoRes);
435	                    mail.AlternateViews.Add(htmlView);
436	                }
437	                else
438	                {
439	                    Logger.Warn("Logo not found at {0}; sending without logo", logoPath);
440	                    mail.Body = htmlBody;
441	                }
442	
443	                foreach (var to in (_smtpSettings.ToEmails ?? Array.Empty<string>()))
444	                    mail.To.Add(to.Trim());
445	
446	                foreach (var cc in (_smtpSettings.CCEmails ?? Array.Empty<string>()))
447	                    mail.CC.Add(cc.Trim());
448	
449	                using (var fs = new FileStream(
450	                    filePath, FileMode.Open, FileAccess.Read, FileShare.Read))
451	                {
452	                    mail.Attachments.Add(new Attachment(fs, Path.GetFileName(filePath)));
453	
454	                    using var smtp = new SmtpClient(
455	                        _smtpSettings.Host, _smtpSettings.SmtpPort)
456	                    {
457	                        Credentials = new NetworkCredential(
458	                            _smtpSettings.username, _smtpSettings.password),
459	                        EnableSsl = _smtpSettings.enableSsl
460	                    };
461	                    await smtp.SendMailAsync(mail);
462	                }
463	
464	                Logger.Info("Email sent: {0}", Path.GetFileName(filePath));
465	
466	                if (File.Exists(filePath))
467	                {
468	                    File.Delete(filePath);
469	                    Logger.Info("Deleted report: {0}", filePath);
470	                }
471	            }
472	            catch (Exception ex)
473	            {
474	                Logger.Error(ex, "Email send failed");
475	            }
476	        }
477	    }
478	}

